  best=(99,None,None)
  for dr in range(4):
   for dc in range(4):
    if (dr,dc)==(0,0): continue
    # orbit under generator v on Z4^2
    seen=set(); pred=np.zeros_like(M); changes=0
    for r in range(4):
     for c in range(4):
      if (r,c) in seen: continue
      orbit=[]; x=(r,c)
      while x not in orbit:
       orbit.append(x); seen.add(x); x=((x[0]+dr)%4,(x[1]+dc)%4)
      ones=sum(M[x] for x in orbit)
      val=int(ones*2>=len(orbit))
      for x in orbit: pred[x]=val
      changes+=min(ones,len(orbit)-ones)
    if changes<best[0]: best=(changes,(dr,dc),pred.copy())
  print((i,j),best[0],best[1])

