  for dr in range(-3,4):
   for dc in range(-3,4):
    if not (dr or dc): continue
    # only non-wrapped pairs
    edges=[]
    for r in range(4):
     for c in range(4):
      rr,cc=r+dr,c+dc
      if 0<=rr<4 and 0<=cc<4: edges.append(((r,c),(rr,cc)))
    # union find
    par=list(range(16))
    def find(x):
     while par[x]!=x: par[x]=par[par[x]]; x=par[x]
     return x
    def union(a,b):
     x,y=find(a),find(b)
     if x!=y:par[y]=x
    for (r,c),(rr,cc) in edges: union(r*4+c,rr*4+cc)
    comps=defaultdict(list)
    for r in range(4):
     for c in range(4): comps[find(r*4+c)].append(M[r,c])
    cost=sum(min(sum(v),len(v)-sum(v)) for v in comps.values())
    if cost<best[0]:best=(cost,(dr,dc))
  print((i,j),best)

