# Calculate non-wrapping rectangular period constraints, allowing any p,q 1..3
for i in range(4):
 for j in range(4):
  M=B[i*4+j]
  cand=[]
  for p in range(1,4):
   for q in range(1,4):
    # reference cell at mod p,q; count majority in each equivalence class
    classes=defaultdict(list)
    for r in range(4):
     for c in range(4): classes[(r%p,c%q)].append(M[r,c])
    cost=sum(min(sum(v),len(v)-sum(v)) for v in classes.values())
    cand.append((cost,p,q))
  print((i,j),sorted(cand)[:3])
